/**
 * Real WASM engine — the Rust engine compiled to WebAssembly.
 *
 * The module is generated by `wasm-pack` from
 * `crates/openpixel-wasm` (`--target web`) into `public/wasm/`:
 *
 *   npm run build:wasm
 *
 * It is loaded lazily, exactly once, with a plain dynamic import of
 * the generated glue file. The `@vite-ignore` comment is deliberate:
 * the package is a *generated* asset that may legitimately be absent
 * (a fresh checkout that never ran `build:wasm`), and Vite must not
 * fail the app build over a file that is optional at runtime. When
 * the import fails — no package, no WebAssembly, an old browser —
 * every function here resolves to `null` and the caller falls back
 * to the canvas path, which is the behaviour the app shipped with
 * before WASM existed. Nothing here ever throws for a missing
 * engine; a conversion that the engine itself rejects (unknown
 * source, AVIF, an unencodable target) also resolves to `null` so
 * the caller can try the next path and, failing that, say so
 * honestly.
 *
 * What the WASM engine adds over the canvas path (see docs/WEB.md):
 * sources TIFF / QOI / HEIC / HEIF / JXL / JPEG 2000 / ICO / PNM /
 * TGA / EXR / HDR and targets TIFF / QOI / HEIC / HEIF / JXL /
 * JPEG 2000 / ICO / PNM / TGA / GIF — all decoded/encoded by the
 * real Rust engine in the browser. AVIF is NOT available in WASM
 * (its decoder needs the native libdav1d C library, which has no
 * wasm32 build); the engine reports that, and this module never
 * claims otherwise.
 *
 * SVG is a WASM source too, even for canvas targets (JPEG/PNG/WebP):
 * the canvas worker decodes with `createImageBitmap`, which rejects
 * every SVG blob ("The source image could not be decoded") while an
 * `<img>` displays the same file fine — so the canvas path cannot
 * convert SVG at all, and the WASM engine (resvg) is the only
 * in-browser route. `wasmCoversConversion` routes SVG there; the
 * preview still uses an `<img>`, which is unaffected.
 *
 * The WASM conversion runs synchronously on the calling thread, so
 * `convertImage` only uses it for conversions the canvas path
 * cannot do at all — the worker-based canvas path stays the default
 * for PNG / JPEG / WebP, where it is already correct and
 * non-blocking. BMP targets also go through WASM: the canvas
 * cannot encode BMP (`toBlob` silently returns PNG for it).
 */
import { useEffect, useState } from 'react'
import { BROWSER_DECODABLE, BROWSER_ENCODABLE, formatById } from './capabilities'

export interface WasmSupport {
  decode: string[]
  encode: string[]
}

export interface WasmImageInfo {
  format: string
  width: number
  height: number
  color_type: string
  has_alpha: boolean
  file_size_bytes: number
  is_animated: boolean
  frame_count: number | null
  note: string | null
  orientation: number | null
  has_exif: boolean
  has_icc: boolean
  has_xmp: boolean
}

/** The generated wasm-pack `--target web` package, typed loosely. */
export interface WasmPackage {
  default: () => Promise<void>
  detect: (bytes: Uint8Array) => string
  info: (bytes: Uint8Array) => WasmImageInfo
  capabilities: () => unknown
  supported_formats: () => WasmSupport
  convert: (
    bytes: Uint8Array,
    target: string,
    quality: number | undefined,
    background: string | undefined,
  ) => Uint8Array
  process: (
    bytes: Uint8Array,
    opsJson: string,
    target: string,
    quality: number | undefined,
    background: string | undefined,
    pngCompression: number | undefined,
  ) => WasmProcessResult
  process_to_size: (
    bytes: Uint8Array,
    opsJson: string,
    target: string,
    // u64 in Rust is a BigInt on the JS side (wasm-bindgen).
    targetBytes: bigint,
    background: string | undefined,
  ) => WasmTargetSizeResult
  version: () => string
  // PDF (Studio Phase 2) — see src/lib/pdf.ts. `pdf_process`
  // returns a JS Array of Uint8Array (one per output document);
  // `pdf_merge` / `pdf_from_images` take JS arrays of Uint8Array.
  // There is NO pdf render export: PDFium needs a native
  // libpdfium binary and cannot run in the browser — the web UI
  // renders PDF pages with pdf.js instead.
  pdf_info: (bytes: Uint8Array) => PdfInfo
  pdf_process: (bytes: Uint8Array, opsJson: string) => Uint8Array[]
  pdf_merge: (documents: unknown) => Uint8Array
  pdf_from_images: (images: unknown, pageSize: string | undefined) => Uint8Array
  // PDF compression (Studio Phase 3) — see src/lib/pdf.ts.
  pdf_compress: (bytes: Uint8Array, optionsJson: string) => WasmPdfCompressResult
  // PDF editing (Studio Phase 5) — see src/lib/pdf.ts. No sign
  // export: signing needs a private key, which must never be
  // handed to a web page — sign with the native CLI or desktop
  // app instead.
  pdf_edit: (bytes: Uint8Array, opsJson: string, images: unknown) => WasmPdfEditResult
  pdf_redact: (bytes: Uint8Array, redactionsJson: string) => WasmPdfRedactResult
  pdf_flatten: (bytes: Uint8Array) => WasmPdfFlattenResult
  pdf_set_metadata: (bytes: Uint8Array, metadataJson: string) => Uint8Array
  pdf_sanitize: (bytes: Uint8Array) => WasmPdfSanitizeResult
  pdf_repair: (bytes: Uint8Array) => WasmPdfRepairResult
  pdf_inspect: (bytes: Uint8Array) => WasmPdfThreats
}

/** What the WASM `pdf_edit` export returns: edited bytes + outcome. */
export interface WasmPdfEditResult {
  data: Uint8Array<ArrayBuffer>
  ops_applied: number
  pages_touched: number
  comments_added: number
  warnings: string[]
}

/** What the WASM `pdf_redact` export returns: redacted bytes + outcome. */
export interface WasmPdfRedactResult {
  data: Uint8Array<ArrayBuffer>
  pages_touched: number
  runs_removed: number
  characters_removed: number
  annotations_removed: number
  redacted_texts: string[]
  warnings: string[]
}

/** What the WASM `pdf_flatten` export returns. */
export interface WasmPdfFlattenResult {
  data: Uint8Array<ArrayBuffer>
  annotations_flattened: number
  annotations_dropped: number
  form_fields_removed: number
  warnings: string[]
}

/** What the WASM `pdf_sanitize` export returns. */
export interface WasmPdfSanitizeResult {
  data: Uint8Array<ArrayBuffer>
  javascript_removed: number
  embedded_files_removed: number
  launch_actions_removed: number
  auto_actions_removed: number
  warnings: string[]
}

/** What the WASM `pdf_repair` export returns. */
export interface WasmPdfRepairResult {
  data: Uint8Array<ArrayBuffer>
  recovery: string
  warnings: string[]
}

/** What the WASM `pdf_inspect` export returns: the threats found. */
export interface WasmPdfThreats {
  javascript: string[]
  embedded_files: string[]
  launch_actions: string[]
  auto_actions: string[]
  warnings: string[]
}

/** What the WASM `pdf_compress` export returns: compressed bytes + measured outcome. */
export interface WasmPdfCompressResult {
  /** Fresh `ArrayBuffer`-backed copy, so `new Blob([bytes])` type-checks. */
  data: Uint8Array<ArrayBuffer>
  input_bytes: number
  output_bytes: number
  saved_bytes: number
  saved_percent: number
  images_recompressed: number
  images_skipped: number
  note: string | null
}

/** What the WASM `process` export returns: resized bytes + result metadata. */
export interface WasmProcessResult {
  /** Fresh `ArrayBuffer`-backed copy, so `new Blob([bytes])` type-checks. */
  bytes: Uint8Array<ArrayBuffer>
  width: number
  height: number
  warnings: string[]
}

/** What the WASM `process_to_size` export returns. */
export interface WasmTargetSizeResult extends WasmProcessResult {
  /** Quality the search settled on; `null` for PNG (compression level is the knob). */
  quality: number | null
  target_met: boolean
}

/**
 * What the WASM `pdf_info` export returns — the `PdfInfo` from
 * `openpixel-pdf` (`inspect`): page count, PDF version, document
 * metadata, encryption flag, and the effective page size in
 * points (width, height) per page, in page order.
 */
export interface PdfInfo {
  page_count: number
  version: string
  title: string | null
  author: string | null
  creator: string | null
  producer: string | null
  encrypted: boolean
  /** Encryption details from the /Encrypt dict; null unless
   * `encrypted` is true. `page_count` is 0 for encrypted files
   * (unknown without the password) — see docs/PDF.md. */
  encryption: {
    algorithm: string
    revision: number | null
    print: boolean
    modify: boolean
    copy: boolean
    annotate: boolean
  } | null
  page_sizes: [number, number][]
}

const WASM_URL = '/wasm/openpixel_wasm.js'

let loadPromise: Promise<WasmPackage | null> | null = null

/** Load (once) and initialise the WASM module; `null` when absent. */
export function loadWasmEngine(): Promise<WasmPackage | null> {
  if (!loadPromise) {
    loadPromise = (async () => {
      try {
        const mod = (await import(/* @vite-ignore */ WASM_URL)) as WasmPackage
        await mod.default()
        return mod
      } catch {
        return null
      }
    })()
  }
  return loadPromise
}

/** What this build of the engine can decode / encode; `null` when absent. */
export async function getWasmSupport(): Promise<WasmSupport | null> {
  const mod = await loadWasmEngine()
  if (!mod) return null
  try {
    return mod.supported_formats()
  } catch {
    return null
  }
}

/**
 * Sources the canvas path cannot decode at all, even though an
 * `<img>` can display them — so `wasmCoversConversion` routes them
 * to the WASM engine instead of letting the worker fail.
 *
 * SVG is the one (verified 16 Nov 2026 on the live site: every SVG
 * — plain rect+text, viewBox-only, Bengali/Arabic text, foreignObject,
 * embedded or external image — failed in the worker with
 * "The source image could not be decoded", while the `<img>` preview
 * rendered each one). `createImageBitmap` rejects SVG blobs; the
 * WASM engine rasterises them with resvg. The preview stays an
 * `<img>` and is unaffected, and `BROWSER_DECODABLE` still lists SVG
 * for display purposes — this list is about the *conversion* path.
 */
const CANVAS_UNDECODABLE: readonly string[] = ['svg']

/**
 * Whether the WASM engine is the right path for this conversion:
 * the engine is loaded, it can decode the source and encode the
 * target, and the canvas path cannot do the conversion (source the
 * browser cannot decode, a source `createImageBitmap` rejects such
 * as SVG, or a target the canvas cannot encode).
 * Pure function of its arguments — unit-tested, no I/O.
 */
export function wasmCoversConversion(
  sourceFormat: string,
  targetFormat: string,
  support: WasmSupport | null,
): boolean {
  if (!support) return false
  if (!support.decode.includes(sourceFormat)) return false
  if (!support.encode.includes(targetFormat)) return false
  return (
    !BROWSER_DECODABLE.includes(sourceFormat) ||
    CANVAS_UNDECODABLE.includes(sourceFormat) ||
    !BROWSER_ENCODABLE.includes(targetFormat)
  )
}

export interface WasmConvertedImage {
  /** Fresh `ArrayBuffer`-backed copy, so `new Blob([bytes])` type-checks. */
  bytes: Uint8Array<ArrayBuffer>
  width: number
  height: number
  /** MIME type of the output, from the engine capability data. */
  mimeType: string
}

/**
 * Convert `bytes` to `targetFormat` with the WASM engine. Returns
 * `null` when the engine is absent or cannot do this conversion —
 * the caller falls back to the canvas path. `background` is the hex
 * colour alpha is flattened to for targets without alpha
 * (`#ffffff` when omitted); it is honoured by the engine, unlike
 * the canvas path's PNG-compression knob.
 */
export async function convertWithWasm(
  bytes: Uint8Array,
  targetFormat: string,
  quality: number,
  background: string | null,
): Promise<WasmConvertedImage | null> {
  const mod = await loadWasmEngine()
  if (!mod) return null
  try {
    const sourceFormat = mod.detect(bytes)
    const support = mod.supported_formats()
    if (!support.decode.includes(sourceFormat)) return null
    if (!support.encode.includes(targetFormat)) return null
    const out = mod.convert(bytes, targetFormat, quality, background ?? undefined)
    const outInfo = mod.info(out)
    const mimeType = formatById(targetFormat)?.mime_types[0] ?? 'application/octet-stream'
    // Copy into a fresh ArrayBuffer-backed array: the bytes wasm-bindgen
    // hands back are typed `Uint8Array<ArrayBufferLike>`, which
    // `new Blob([…])` rejects under this repo's strict TypeScript.
    return { bytes: new Uint8Array(out), width: outInfo.width, height: outInfo.height, mimeType }
  } catch {
    return null
  }
}

/**
 * Read format + dimensions with the WASM engine. Returns `null`
 * when the engine is absent or cannot decode the bytes — the caller
 * falls back to `createImageBitmap`.
 */
export async function probeWithWasm(
  bytes: Uint8Array,
): Promise<{ format: string; width: number; height: number } | null> {
  const mod = await loadWasmEngine()
  if (!mod) return null
  try {
    const format = mod.detect(bytes)
    if (format === 'unknown') return null
    const info = mod.info(bytes)
    return { format, width: info.width, height: info.height }
  } catch {
    return null
  }
}

export interface WasmProcessOptions {
  opsJson: string
  quality: number
  background: string | null
  pngCompression: number
}

/**
 * Resize `bytes` with the WASM engine (the real Rust engine,
 * Lanczos3). Returns `null` when the engine is absent or cannot do
 * this resize — the caller falls back to the canvas path. Unlike
 * `convertWithWasm`, resize prefers WASM even for canvas targets:
 * the canvas scaler is bilinear, and the point of this feature is
 * quality. The result bytes are copied into a fresh
 * `ArrayBuffer`-backed array, like `convertWithWasm`.
 */
export async function processWithWasm(
  bytes: Uint8Array,
  targetFormat: string,
  options: WasmProcessOptions,
): Promise<WasmProcessResult | null> {
  const mod = await loadWasmEngine()
  if (!mod) return null
  try {
    const sourceFormat = mod.detect(bytes)
    const support = mod.supported_formats()
    if (!support.decode.includes(sourceFormat)) return null
    if (!support.encode.includes(targetFormat)) return null
    const out = mod.process(
      bytes,
      options.opsJson,
      targetFormat,
      options.quality,
      options.background ?? undefined,
      options.pngCompression,
    )
    return {
      bytes: new Uint8Array(out.bytes),
      width: out.width,
      height: out.height,
      warnings: out.warnings,
    }
  } catch {
    return null
  }
}

/**
 * Resize + compress `bytes` to fit `targetBytes` with the WASM
 * engine (the engine's binary search over quality — see
 * `Engine::process_to_size_bytes`). Returns `null` when the engine
 * is absent or rejects the search (e.g. a WebP target, which the
 * engine encodes losslessly only) — the caller reports that
 * honestly instead of faking a fit. There is no canvas equivalent:
 * a target-size search without the engine is not offered.
 */
export async function processToSizeWithWasm(
  bytes: Uint8Array,
  targetFormat: string,
  options: WasmProcessOptions & { targetBytes: number },
): Promise<WasmTargetSizeResult | null> {
  const mod = await loadWasmEngine()
  if (!mod) return null
  try {
    const sourceFormat = mod.detect(bytes)
    const support = mod.supported_formats()
    if (!support.decode.includes(sourceFormat)) return null
    if (!support.encode.includes(targetFormat)) return null
    const out = mod.process_to_size(
      bytes,
      options.opsJson,
      targetFormat,
      BigInt(options.targetBytes),
      options.background ?? undefined,
    )
    return {
      bytes: new Uint8Array(out.bytes),
      width: out.width,
      height: out.height,
      warnings: out.warnings,
      quality: out.quality,
      target_met: out.target_met,
    }
  } catch {
    return null
  }
}

/**
 * Merge the browser's format list with the WASM engine's,
 * deduplicated, browser formats first. Pure — unit-tested.
 */
export function mergeFormatLists(
  browser: readonly string[],
  wasm: readonly string[] | undefined,
): string[] {
  return [...browser, ...(wasm ?? []).filter((f) => !browser.includes(f))]
}

/**
 * React hook: the WASM engine's format support, loaded once on
 * mount. `null` while loading *and* when the engine is absent — the
 * two are indistinguishable on purpose: the UI must work identically
 * with or without the module, just with fewer formats offered.
 */
export function useWasmSupport(): WasmSupport | null {
  const [support, setSupport] = useState<WasmSupport | null>(null)
  useEffect(() => {
    let live = true
    getWasmSupport().then((s) => {
      if (live) setSupport(s)
    })
    return () => {
      live = false
    }
  }, [])
  return support
}
